package miners

import (
	"strings"
	"testing"
)

// Template layout as generated by VerthashMiner 0.7.2 with --no-restrict-cuda:
// OpenCL devices 0 (RTX 5080), 1 (GTX 1080) and 2 (AMD), CUDA devices 0 and 1.
const testTemplate = `# OpenCL device config:
#
# Available platforms:
#
# 1. Platform name: NVIDIA Corporation
#    Index: 0
# 2. Platform name: Advanced Micro Devices, Inc.
#    Index: 1
#
# Available devices:
#
# DeviceIndex: 0
#    Name: NVIDIA GeForce RTX 5080
#    PCIeId: 2b:00:0
#    Platform index: 0
#
# DeviceIndex: 1
#    Name: NVIDIA GeForce GTX 1080
#    PCIeId: 0a:00:0
#    Platform index: 0
#
# DeviceIndex: 2
#    Name: Radeon RX 580
#    PCIeId: 03:00:0
#    Platform index: 1
#
#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#

<CL_Device0 DeviceIndex = "0" BinaryFormat = "auto" AsmProgram = "none" WorkSize = "0">
<CL_Device1 DeviceIndex = "1" BinaryFormat = "auto" AsmProgram = "none" WorkSize = "0">
<CL_Device2 DeviceIndex = "2" BinaryFormat = "auto" AsmProgram = "none" WorkSize = "0">

#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#
# CUDA Device config:
#
# Available devices:
#
# DeviceIndex: 0
#    Name: NVIDIA GeForce RTX 5080
#    PCIeId: 2b:00:0
#
# DeviceIndex: 1
#    Name: NVIDIA GeForce GTX 1080
#    PCIeId: 0a:00:0
#
#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#-#

<CU_Device0 DeviceIndex = "0" WorkSize = "0" BatchTimeMs = "500">
<CU_Device1 DeviceIndex = "1" WorkSize = "0" BatchTimeMs = "500">
`

func deviceLines(lines []string) []string {
	var out []string
	for _, l := range lines {
		if strings.HasPrefix(l, "<CL_Device") || strings.HasPrefix(l, "<CU_Device") {
			out = append(out, strings.SplitN(l, " ", 2)[0])
		}
	}
	return out
}

func TestSelectVerthashDevices(t *testing.T) {
	lines := strings.Split(testTemplate, "\n")
	cases := []struct {
		name string
		caps map[string]float64
		want []string
	}{
		{
			// RTX 5080 (12.0) can't run the CUDA 11 build -> OpenCL; GTX 1080 (6.1) stays on CUDA.
			name: "unsupported card falls back to OpenCL",
			caps: map[string]float64{"2b:00:0": 12.0, "0a:00:0": 6.1},
			want: []string{"<CL_Device0", "<CL_Device2", "<CU_Device1"},
		},
		{
			// Without nvidia-smi data every NVIDIA card keeps CUDA, as before.
			name: "no compute capability info keeps CUDA",
			caps: nil,
			want: []string{"<CL_Device2", "<CU_Device0", "<CU_Device1"},
		},
	}
	for _, c := range cases {
		got := deviceLines(selectVerthashDevices(lines, c.caps))
		if strings.Join(got, ",") != strings.Join(c.want, ",") {
			t.Errorf("%s: got %v, want %v", c.name, got, c.want)
		}
	}
}

func TestNormalizePCIeID(t *testing.T) {
	for in, want := range map[string]string{
		"00000000:2B:00.0": "2b:00:0",
		"0000:0A:00.0":     "0a:00:0",
		"2b:00:0":          "2b:00:0",
	} {
		if got := normalizePCIeID(in); got != want {
			t.Errorf("normalizePCIeID(%q) = %q, want %q", in, got, want)
		}
	}
}
